package com.jnapanam.sportszone.promotion.model;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.payment.model.PaymentOrder;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="promotion_redemptions")public class PromotionRedemption{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="promotion_id")private Promotion promotion;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="payment_order_id")private PaymentOrder paymentOrder;@Column(name="discount_paise",nullable=false)private long discountPaise;@Column(name="redeemed_at",nullable=false)private Instant redeemedAt;public Promotion getPromotion(){return promotion;}protected PromotionRedemption(){}public PromotionRedemption(Promotion p,User u,PaymentOrder o,long d){id=UUID.randomUUID();promotion=p;user=u;paymentOrder=o;discountPaise=d;redeemedAt=Instant.now();}}
